    import java.util.*;

class GfG {

    // Function to find the longest increasing path in a matrix
    static int longIncPath(int[][] matrix) {
        int n = matrix.length;
        int m = matrix[0].length;

        // Direction vectors: right, down, left, up
        int[][] dir = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

        // In-degree matrix
        int[][] degree = new int[n][m];

        // Compute in-degrees
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                for (int[] d : dir) {
                    int x = i + d[0];
                    int y = j + d[1];

                    if (x >= 0 && x < n && y >= 0 && y < m && matrix[x][y] < matrix[i][j]) {
                        degree[i][j]++;
                    }
                }
            }
        }

        // Enqueue all 0 in-degree cells
        Queue<int[]> q = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (degree[i][j] == 0) {
                    q.offer(new int[]{i, j});
                }
            }
        }

        int ans = 0;

        // BFS level-by-level
        while (!q.isEmpty()) {
            ans++;
            int size = q.size();

            for (int i = 0; i < size; i++) {
                int[] cell = q.poll();
                int x1 = cell[0], y1 = cell[1];

                for (int[] d : dir) {
                    int x = x1 + d[0];
                    int y = y1 + d[1];

                    if (x >= 0 && x < n && y >= 0 && y < m && matrix[x][y] > matrix[x1][y1]) {
                        degree[x][y]--;
                        if (degree[x][y] == 0) {
                            q.offer(new int[]{x, y});
                        }
                    }
                }
            }
        }

        return ans;
    }

    public static void main(String[] args) {
        int[][] matrix = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };

        System.out.println(longIncPath(matrix));
    }
}


